s=s.replace('"""Signature checks for the event requests Corvid Payments sends us."""\n','''"""Signature checks for the event requests Corvid Payments sends us."""

import base64
import hashlib
import hmac
''',1)
s=s.replace("    raise NotImplementedError",'''    try:
        return _verify(headers, body, secrets, now)
    except Exception:
        return False


def _verify(headers, body, secrets, now) -> bool:
    lowered = {str(k).lower(): v for k, v in headers.items()}
    event_id = lowered.get("corvid-event-id")
    header = lowered.get("corvid-signature")
    if not isinstance(event_id, str) or not isinstance(header, str) or not event_id:
        return False

    t = None
    sigs = []
    for element in header.split(","):
        element = element.lstrip(" ")
        key, sep, value = element.partition("=")
        if not sep or not key:
            return False
        if key == "t":
            if t is not None:
                return False
            t = value
        elif key == "v2":
            sigs.append(value)
    if t is None or not (t.isascii() and t.isdigit()) or not sigs:
        return False

    ts = int(t)
    if ts < now - 300 or ts > now + 60:
        return False

    payload = b"v2:" + t.encode() + b":" + event_id.encode() + b":" + body
    ok = False
    for secret in secrets:
        if not isinstance(secret, str) or not secret.startswith("whsec_"):
            continue
        try:
            key = base64.b64decode(secret[len("whsec_"):], validate=True)
        except ValueError:
            continue
        expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
        for sig in sigs:
            if hmac.compare_digest(sig.encode(), expected.encode()):
                ok = True
    return ok''')
open(p,'w').write(s)
p='receiver/handler.py'
s=open(p).read()
a=s.index("    try:\n        event")
s=s[:a]+'''    if not verify(headers, body, secrets, now):
        return 401
    try:
        event = json.loads(body)
    except ValueError:
        return 400
    if not isinstance(event, dict):
        return 400
    EVENTS.append(event)
    return 204
'''
open(p,'w').write(s)
E
